                SELECT s2.channel_name as bcn, s2.id as best_id, s2.thumbnail as best_thumb, s2.title as best_title,
                       ROW_NUMBER() OVER (
                           PARTITION BY s2.channel_name
                           ORDER BY COALESCE(t42.hazard_level, 3.0) DESC, s2.published_at DESC
